// --- Constants: SVG Icons ---
const ICON_BROWN = L.divIcon({
  className: 'custom-div-icon',
  html: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#4A3023" width="36px" height="36px" stroke="black" stroke-width="1"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/><circle cx="12" cy="9" r="2.5" fill="white"/></svg>`,
  iconSize: [36, 36],
  iconAnchor: [18, 36],
  popupAnchor: [0, -36]
});
const ICON_GREEN = L.divIcon({
  className: 'custom-div-icon',
  html: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#1D5931" width="48px" height="48px" stroke="black" stroke-width="1"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/><circle cx="12" cy="9" r="2.5" fill="white"/></svg>`,
  iconSize: [48, 48],
  iconAnchor: [24, 48],
  popupAnchor: [0, -48]
});

// --- State Variables ---
let mapInstance = null;
let markersLayer = null;

// --- Helper Functions ---

// 1. Initialize the Map Instance (Runs only once)
function setupMap() {
  const container = document.getElementById('map');
  if (!container) return false;

  // Reset container if needed (fixes re-render issues)
  if (container._leaflet_id) container._leaflet_id = null;
  mapInstance = L.map('map').setView([37.9755, 23.7348], 12);
  L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
    maxZoom: 19,
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
  }).addTo(mapInstance);
  markersLayer = L.layerGroup().addTo(mapInstance);
  return true;
}

// 2. Update Markers based on Data
function updateMarkers(model) {
  if (!mapInstance || !model || !model.locations) return;
  markersLayer.clearLayers();
  const locations = model.locations;
  const selected = model.selectedPoint;
  locations.forEach(location => {
    const {
      coordinates,
      name,
      address
    } = location;
    if (!coordinates || !coordinates.lat || !coordinates.lng) return;

    // Check if this location is currently selected
    const isSelected = selected && selected.lat === coordinates.lat && selected.lng === coordinates.lng;

    // Configure Marker
    const markerIcon = isSelected ? ICON_GREEN : ICON_BROWN;
    const zIndex = isSelected ? 1000 : 0;
    const marker = L.marker([coordinates.lat, coordinates.lng], {
      icon: markerIcon,
      zIndexOffset: zIndex
    });
    marker.bindPopup(`<b>${name}</b><br>${address}`);
    marker.addTo(markersLayer);

    // Zoom logic for selected item
    if (isSelected) {
      mapInstance.flyTo([coordinates.lat, coordinates.lng], 15, {
        animate: true,
        duration: 1.5
      });
      marker.openPopup();
    }
  });
}

// --- Main Entry Point ---

// Wait until Leaflet is loaded
function waitForLeaflet() {
  if (typeof L === 'undefined') {
    setTimeout(waitForLeaflet, 100);
    return;
  }

  // Once Leaflet is ready, signal Appsmith we are ready
  appsmith.onReady(() => {
    const isMapReady = setupMap();
    if (isMapReady) {
      // 1. Render initial state
      updateMarkers(appsmith.model);

      // 2. Listen for future updates (Radio button changes)
      appsmith.onModelChange(model => {
        updateMarkers(model);
      });
    }
  });
}

// Start execution
waitForLeaflet();

