	addItem: (item, quantity) => {
		let currentCart = appsmith.store.cart || [];

		// Check if item already exists to update quantity instead of duplicating
		const existingItemIndex = currentCart.findIndex(cart_item => cart_item.itemid === item.itemid);
		if (existingItemIndex >= 0) {
			currentCart[existingItemIndex].quantity = quantity;
		} else {
			currentCart.push({ ...item, quantity: quantity });
		}

		// Save back to store
		storeValue('cart', currentCart);
		showAlert(`${item.name} added to cart!`, 'success');
	},

