		const cart = appsmith.store.cart || [];
		const targetName = currentItem.name;
		const newQuantity = Number(amount);
		const index = cart.findIndex(item => item.name === targetName);

		if (index !== -1) {
			const updatedCart = [...cart];
			updatedCart[index] = {
				...updatedCart[index],
				quantity: newQuantity
			};
			return storeValue('cart', updatedCart);
		}
	},

	removeItem: (itemid) => {
		let currentCart = appsmith.store.cart || [];
		let newCart = currentCart.filter(item => item.itemid !== itemid);
		storeValue('cart', newCart);
